// GENERATED by agent-config.py. OpenCode V2 only; install after conformance checks.
// API: opencode.ai/v2/docs/build/plugins and v2/packages/plugin/src/promise/tool.ts.
import { spawn } from "node:child_process";
import { request } from "node:http";
import { homedir } from "node:os";
import { join, isAbsolute } from "node:path";
const shim = __CHORUS_SHIM_JSON__;

// A shared OpenCode process has no session-specific role environment. Resolve
// each native ID through the supervisor; never register identities from events.
async function binding(nativeID) {
  if (typeof nativeID !== "string" || !nativeID) throw new Error("Chorus requires a native session identity");
  const payload = JSON.stringify({ runtime: "opencode", native_session_id: nativeID });
  const answer = await new Promise((resolve, reject) => {
    const req = request({
      socketPath: process.env.CHORUS_AGENT_SOCKET || join(homedir(), ".chorus/run/chorus-agent.sock"),
      path: "/v1/native-binding", method: "POST",
      headers: { "content-type": "application/json", "content-length": Buffer.byteLength(payload) }
    }, response => {
      let body = "", size = 0;
      response.on("data", chunk => {
        size += chunk.length;
        if (size > 65536) { response.destroy(); reject(new Error("Chorus binding response too large")); }
        else body += chunk;
      });
      response.on("error", reject);
      response.on("end", () => {
        try {
          if (response.statusCode !== 200) throw new Error("Native session is not registered with Chorus");
          resolve(JSON.parse(body));
        } catch (error) { reject(error); }
      });
    });
    req.setTimeout(2000, () => req.destroy(new Error("Chorus session lookup timed out")));
    req.on("error", reject);
    req.end(payload);
  });
  if (!/^[a-zA-Z0-9-]+$/.test(answer.session_id || "") ||
      !["wren", "silas", "kade"].includes(answer.role) ||
      typeof answer.cwd !== "string" || !isAbsolute(answer.cwd)) {
    throw new Error("Chorus returned an invalid session binding");
  }
  return answer;
}

async function invoke(event, nativeID, payload) {
  const enrolled = await binding(nativeID);
  return new Promise((resolve, reject) => {
    const env = { ...process.env, CHORUS_SESSION_ID: enrolled.session_id,
      CHORUS_ROLE: enrolled.role, DEPLOY_ROLE: enrolled.role };
    const child = spawn(shim, ["runtime-hook", "opencode", event], {
      cwd: enrolled.cwd, env, stdio: ["pipe", "pipe", "pipe"]
    });
    let stdout = "", stderr = "", size = 0;
    const timeout = setTimeout(() => { child.kill(); reject(new Error("Chorus policy hook timed out")); }, 30000);
    child.on("error", error => { clearTimeout(timeout); reject(error); });
    child.stdout.on("data", chunk => {
      size += chunk.length;
      if (size > 1048576) { child.kill(); clearTimeout(timeout); reject(new Error("Chorus policy response too large")); }
      else stdout += chunk;
    });
    child.stderr.on("data", chunk => { if (stderr.length < 4096) stderr += chunk; });
    child.on("close", code => {
      clearTimeout(timeout);
      try {
        if (code !== 0) throw new Error(`Chorus hook failed (${code}): ${stderr}`);
        const answer = JSON.parse(stdout);
        if (!["allow", "deny"].includes(answer.decision)) throw new Error("Chorus hook did not return a decision");
        resolve(answer);
      } catch (error) { reject(error); }
    });
    child.stdin.on("error", error => { clearTimeout(timeout); reject(error); });
    // Only supervisor binding supplies cwd/role/session env. Raw event fields
    // cannot promote enforcement mode or approve capability gaps.
    child.stdin.end(JSON.stringify({ ...payload, cwd: enrolled.cwd, session_id: nativeID }));
  });
}

// Plugin.define is an identity helper in the V2 SDK. Export its documented
// {id, setup} definition directly so a private deployment needs no node_modules.
export default {
  id: "chorus",
  async setup(ctx) {
    await ctx.tool.hook("execute.before", async event => {
      const answer = await invoke("tool.execute.before", event.sessionID, {
        callID: event.id, tool_name: event.tool, tool_input: event.input
      });
      if (answer.decision !== "allow") throw new Error(answer.reason || "Chorus denied the operation");
    });
    await ctx.tool.hook("execute.after", async event => {
      // An observation failure must not turn a completed tool into a retry.
      await invoke("tool.execute.after", event.sessionID, {
        callID: event.id, tool_name: event.tool, tool_input: event.input,
        tool_response: event.status === "completed" ? event.result : event.error,
        tool_output_is_error: event.status === "error"
      }).catch(error => console.error("Chorus observation:", error.message));
    });
    await ctx.session.hook("prompt", async event => {
      const answer = await invoke("UserPromptSubmit", event.sessionID, { prompt: event.prompt.text });
      if (answer.decision === "deny") throw new Error(answer.reason || "Chorus denied the prompt");
      const context = answer.hookSpecificOutput?.additionalContext;
      if (context) event.prompt.text += `\n\n<chorus-context>\n${context}\n</chorus-context>`;
    });
  }
};
